SELECT ?eventUid ?type ?descriptor WHERE {
  {
    ?e a :Process ;
       :eventUid ?eventUid ;
       :cmdLine ?descriptor .
    BIND("Process" AS ?type)
  }
  UNION
  {
    ?e a :ApiEvent ;
       :eventUid ?eventUid ;
       :operation ?descriptor .
    BIND("ApiEvent" AS ?type)
  }
  UNION
  {
    ?e a :Session ;
       :eventUid ?eventUid ;
       :startTime ?descriptor .
    BIND("Session" AS ?type)
  }
}
ORDER BY ?eventUid

