SELECT ?stage ?eventUid ?detail WHERE {
  {
    ?e a :Process ; :eventUid ?eventUid ; :cmdLine ?detail .
    BIND("PowerShell execution" AS ?stage)
    FILTER(CONTAINS(LCASE(STR(?detail)), "powershell"))
  }
  UNION
  {
    ?e a :Process ; :eventUid ?eventUid ; :cmdLine ?detail .
    BIND("C2 beacon" AS ?stage)
    FILTER(CONTAINS(LCASE(STR(?detail)), "beacon") || CONTAINS(LCASE(STR(?detail)), "c2"))
  }
  UNION
  {
    ?e a :Process ; :eventUid ?eventUid ; :cmdLine ?detail .
    BIND("lateral connection" AS ?stage)
    FILTER(CONTAINS(LCASE(STR(?detail)), "lateral") || CONTAINS(LCASE(STR(?detail)), "psexec") || CONTAINS(LCASE(STR(?detail)), "wmic"))
  }
  UNION
  {
    ?e a :ApiEvent ; :eventUid ?eventUid ; :operation ?detail .
    BIND("OAuth consent" AS ?stage)
    FILTER(CONTAINS(LCASE(STR(?detail)), "oauth") || CONTAINS(LCASE(STR(?detail)), "consent"))
  }
  UNION
  {
    ?e a :ApiEvent ; :eventUid ?eventUid ; :operation ?detail ; :mfaPresent ?mfa .
    BIND("no-MFA privilege escalation" AS ?stage)
    FILTER(STR(?mfa) = "false" && (CONTAINS(LCASE(STR(?detail)), "escalat") || CONTAINS(LCASE(STR(?detail)), "privilege")))
  }
  UNION
  {
    ?e a :ApiEvent ; :eventUid ?eventUid ; :operation ?detail .
    BIND("role assumption" AS ?stage)
    FILTER(CONTAINS(LCASE(STR(?detail)), "assumerole") || CONTAINS(LCASE(STR(?detail)), "role"))
  }
  UNION
  {
    ?e a :ApiEvent ; :eventUid ?eventUid ; :operation ?detail .
    BIND("data exfiltration" AS ?stage)
    FILTER(CONTAINS(LCASE(STR(?detail)), "exfil") || CONTAINS(LCASE(STR(?detail)), "getobject") || CONTAINS(LCASE(STR(?detail)), "download"))
  }
  UNION
  {
    ?e a :Session ; :eventUid ?eventUid ; :startTime ?detail .
    BIND("lateral connection" AS ?stage)
  }
}
ORDER BY ?eventUid

SELECT ?event ?type ?eventUid ?startTime WHERE {
  {
    ?event a :Process ; :eventUid ?eventUid .
    BIND("Process" AS ?type)
    OPTIONAL { ?event :startTime ?startTime }
  }
  UNION
  {
    ?event a :ApiEvent ; :eventUid ?eventUid .
    BIND("ApiEvent" AS ?type)
    OPTIONAL { ?event :startTime ?startTime }
  }
  UNION
  {
    ?event a :Session ; :eventUid ?eventUid ; :startTime ?startTime .
    BIND("Session" AS ?type)
  }
}
ORDER BY ?startTime ?eventUid

SELECT (COUNT(DISTINCT ?host) AS ?distinctAssets)
WHERE {
  {
    ?apiEv a :ApiEvent ; :actor ?actorUid ; :eventUid ?uid .
    ?proc a :Process ; :eventUid ?uid ; :host ?host .
  }
  UNION
  {
    ?apiEv a :ApiEvent ; :actor ?actorUid ; :eventUid ?uid .
    ?sess a :Session ; :eventUid ?uid ; :host ?host .
  }
}

SELECT (COUNT(DISTINCT ?host) AS ?distinctAssets)
WHERE {
  ?api a :ApiEvent ;
       :actor ?actorUid ;
       :eventUid ?eid .
  {
    ?proc a :Process ;
          :eventUid ?eid ;
          :host ?host .
  } UNION {
    ?sess a :Session ;
          :eventUid ?eid ;
          :host ?host .
  }
  {
    SELECT DISTINCT ?actorUid
    WHERE {
      ?api2 a :ApiEvent ;
            :actor ?actorUid .
    }
    LIMIT 6
  }
}

SELECT (COUNT(DISTINCT ?host) AS ?distinctAssets)
WHERE {
  {
    ?api a :ApiEvent ; :eventUid ?eid ; :actor ?actorUid .
    ?proc a :Process ; :eventUid ?eid ; :host ?host .
  }
  UNION
  {
    ?api a :ApiEvent ; :eventUid ?eid ; :actor ?actorUid .
    ?sess a :Session ; :eventUid ?eid ; :host ?host .
  }
}

SELECT (COUNT(DISTINCT ?host) AS ?distinctAssets)
WHERE {
  {
    SELECT DISTINCT ?actorUid
    WHERE {
      ?api a :ApiEvent ;
           :actor ?actorUid .
    }
  }
  {
    ?api2 a :ApiEvent ;
          :actor ?actorUid ;
          :eventUid ?eid .
    ?proc a :Process ;
          :eventUid ?eid ;
          :host ?host .
  }
  UNION
  {
    ?api2 a :ApiEvent ;
          :actor ?actorUid ;
          :eventUid ?eid .
    ?sess a :Session ;
          :eventUid ?eid ;
          :host ?host .
  }
}

